changeSet.sql:
create table if not exists sales ( id Int64, sign Int8, version Int64, createdDateTime DateTime, uid String, originUid Nullable(String), fiscalUrl Nullable(String), shiftNumber Nullable(Int64), costAmount Decimal(25, 2), totalCost Decimal(25, 2), type LowCardinality(String), status LowCardinality(String), source LowCardinality(String), payments Map(String, Decimal(25, 2)), branchId Int64, branchName String, branchActivityId Nullable(Int64), branchRegionId Nullable(Int64), branchCityId Nullable(Int64), companyId Int64, companyName String, companyTin String, customer Nullable(String), createdById Int64, createdByName String, terminalSN Nullable(String), facturaId Nullable(String), searchField String, salesDetailIds Array(Int64), info String ) engine = VersionedCollapsingMergeTree(sign, version) partition by toYYYYMM(createdDateTime) order by (createdDateTime, companyId, branchId, uid);
create table if not exists sales_kafka ( id Int64, sign Int8, version Int64, createdDateTime DateTime, uid String, originUid Nullable(String), fiscalUrl Nullable(String), shiftNumber Nullable(Int64), costAmount Decimal(25, 2), totalCost Decimal(25, 2), type LowCardinality(String), status LowCardinality(String), source LowCardinality(String), payments Map(String, Decimal(25, 2)), branchId Int64, branchName String, branchActivityId Nullable(Int64), branchRegionId Nullable(Int64), branchCityId Nullable(Int64), companyId Int64, companyName String, companyTin String, customer Nullable(String), createdById Int64, createdByName String, terminalSN Nullable(String), facturaId Nullable(String), searchField String, salesDetailIds Array(Int64), info String ) engine Kafka('localhost:9092', 'sales', 'clickhouse-sales', 'JSONEachRow');
create materialized view if not exists sales_mv to sales as select * from sales_kafka;

ALTER TABLE sales ADD COLUMN promotionId Int64;
DROP TABLE IF EXISTS sales_kafka; create table sales_kafka ( id Int64, sign Int8, version Int64, createdDateTime DateTime, uid String, originUid Nullable(String), fiscalUrl Nullable(String), shiftNumber Nullable(Int64), costAmount Decimal(25, 2), totalCost Decimal(25, 2), type LowCardinality(String), status LowCardinality(String), source LowCardinality(String), payments Map(String, Decimal(25, 2)), branchId Int64, branchName String, branchActivityId Nullable(Int64), branchRegionId Nullable(Int64), branchCityId Nullable(Int64), companyId Int64, companyName String, companyTin String, customer Nullable(String), createdById Int64, createdByName String, terminalSN Nullable(String), facturaId Nullable(String), searchField String, salesDetailIds Array(Int64), info String, promotionId Int64 ) engine Kafka('localhost:9092', 'sales', 'clickhouse-sales', 'JSONEachRow');
DROP VIEW IF EXISTS sales_mv;
create materialized view if not exists sales_mv to sales as select * from sales_kafka;
